using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Collections.Generic;
using System.Runtime.Serialization;
namespace Ara {
 [DataContract] public class ReplicaInput {[DataMember]public string date,baseState,localState,expectedRevision;[DataMember]public bool preferLocal;}
 [DataContract] public class ReplicaReply {[DataMember]public string state,revision;[DataMember]public PhoneDay view;}
 public static class ReplicaSync {
  static bool Same<T>(T a,T b){return PhoneCodec.Hash(PhoneCodec.Json(a))==PhoneCodec.Hash(PhoneCodec.Json(b));}
  static T Pick<T>(T b,T l,T c,string path,bool force){if(Same(b,l))return c;if(Same(b,c)||Same(l,c)||force)return l;throw new SyncConflict("양쪽에서 같은 부분을 수정했습니다: "+path+". 두 기록을 보관한 상태에서 사용할 내용을 선택해 주세요.");}
  static List<T> Entities<T>(List<T> b,List<T> l,List<T> c,Func<T,string> key,string path,bool force) where T:class {var result=new List<T>();foreach(string id in c.Select(key).Concat(l.Select(key)).Distinct()){var old=b.FirstOrDefault(x=>key(x)==id);var a=l.FirstOrDefault(x=>key(x)==id);var z=c.FirstOrDefault(x=>key(x)==id);var value=Pick(old,a,z,path+"/"+id,force);if(value!=null)result.Add(value);}return result;}
  static Dictionary<string,T> Map<T>(Dictionary<string,T> b,Dictionary<string,T> l,Dictionary<string,T> c,string path,bool force){var result=new Dictionary<string,T>();foreach(string k in b.Keys.Concat(l.Keys).Concat(c.Keys).Distinct()){T old=default(T),a=default(T),z=default(T);b.TryGetValue(k,out old);l.TryGetValue(k,out a);c.TryGetValue(k,out z);var value=Pick(old,a,z,path+"/"+k,force);if(l.ContainsKey(k)||c.ContainsKey(k))result[k]=value;}return result;}
  static List<string> Set(List<string> b,List<string> l,List<string> c){return b.Concat(l).Concat(c).Distinct().Where(k=>l.Contains(k)==b.Contains(k)?c.Contains(k):l.Contains(k)).ToList();}
  static string Value(CellBlock b){if(b==null)return "null";return JsonMap.Write(new object[]{b.TaskId??"",b.Name,b.Category,b.Score,b.Satisfaction,b.TemplateId,b.MealId,b.PrepFor,b.Priority,b.Minimum});}
  static CellBlock[] Cells(List<CellBlock> list,DateTime date){var cells=new CellBlock[288];foreach(var b in list){int start=(int)(b.Start-date).TotalMinutes/10;for(int i=start;i<start+b.Count;i++){if(i<0||i>=288||cells[i]!=null)throw new InvalidDataException("동기화할 시간 범위가 잘못되었습니다.");cells[i]=b;}}return cells;}
  static List<CellBlock> Blocks(List<CellBlock> old,List<CellBlock> local,List<CellBlock> current,DateTime date,string path,bool force){
   foreach(var b in old){var a=local.Find(x=>x.Id==b.Id);var c=current.Find(x=>x.Id==b.Id);if(!force&&a!=null&&c!=null&&a.Start!=b.Start&&c.Start!=b.Start&&a.Start!=c.Start)throw new SyncConflict("같은 블록을 서로 다른 시각으로 옮겼습니다: "+path);}
   var baseline=Cells(old,date);var mine=Cells(local,date);var remote=Cells(current,date);var result=new List<CellBlock>();var used=new HashSet<string>();string runSource=null;
   for(int i=0;i<288;i++){var a=mine[i];var c=remote[i];var b=baseline[i];string bv=Value(b),av=Value(a),cv=Value(c);CellBlock chosen;if(av==bv)chosen=c;else if(cv==bv||av==cv||force)chosen=a;else throw new SyncConflict("같은 시간 칸을 양쪽에서 수정했습니다: "+path+" "+date.AddMinutes(i*10).ToString("HH:mm"));if(chosen==null){runSource=null;continue;}var last=result.LastOrDefault();if(last!=null&&last.End==date.AddMinutes(i*10)&&Value(last)==Value(chosen)&&runSource==chosen.Id){last.Count++;continue;}var part=chosen.Copy();part.Start=date.AddMinutes(i*10);part.Count=1;if(!used.Add(part.Id)){part.Id=Guid.NewGuid().ToString("N");used.Add(part.Id);}result.Add(part);runSource=chosen.Id;}
   return result;
  }
  static List<Todo> Tasks(List<Todo> baseline,List<Todo> local,List<Todo> current,bool force){var result=new List<Todo>();foreach(string key in baseline.Select(x=>x.Id).Concat(local.Select(x=>x.Id)).Concat(current.Select(x=>x.Id)).Distinct()){var b=baseline.Find(x=>x.Id==key);var l=local.Find(x=>x.Id==key);var c=current.Find(x=>x.Id==key);if(b!=null&&l!=null&&c!=null)result.Add(new Todo{Id=key,Text=Pick(b.Text,l.Text,c.Text,"과제 내용",force),Group=Pick(b.Group,l.Group,c.Group,"과제 그룹",force),DoneDates=Set(b.DoneDates,l.DoneDates,c.DoneDates)});else{var chosen=Pick(b,l,c,"과제",force);if(chosen!=null)result.Add(chosen);}}return result;}
  public static State Merge(State baseline,State local,State current,string date,bool force=false){
   Engine.Validate(baseline);Engine.Validate(local);var merged=Store.Clone(current);var b=baseline.Days.Single(x=>x.Date==date);var l=local.Days.Single(x=>x.Date==date);var c=merged.GetDay(PhoneCodec.Date(date));var d=new Day{Date=date};
   d.AdherenceState=Adherence.Merge(b.AdherenceState,l.AdherenceState,c.AdherenceState,force);
   d.WakeConfirmed=Pick(b.WakeConfirmed,l.WakeConfirmed,c.WakeConfirmed,"기상 확정",force);d.Wake=Pick(b.Wake,l.Wake,c.Wake,"기상",force);d.Note=Pick(b.Note,l.Note,c.Note,"메모",force);d.Actual=Map(b.Actual,l.Actual,c.Actual,"실제 시각",force);d.Done=Set(b.Done,l.Done,c.Done);d.Notified=c.Notified.ToList();d.GridReady=Pick(b.GridReady,l.GridReady,c.GridReady,"계획 형식",force);d.StartAnchoredMeals=Pick(b.StartAnchoredMeals,l.StartAnchoredMeals,c.StartAnchoredMeals,"계획 기준",force);d.ManualPlan=Pick(b.ManualPlan,l.ManualPlan,c.ManualPlan,"직접 수정 계획",force);d.ShowerAfterSecond=Pick(b.ShowerAfterSecond,l.ShowerAfterSecond,c.ShowerAfterSecond,"샤워 순서",force);
   DateTime origin=PhoneCodec.Date(date);d.Records=Blocks(b.Records,l.Records,c.Records,origin,"실제",force);d.GridBase=Blocks(b.GridBase,l.GridBase,c.GridBase,origin,"계획",force);d.PlanHistory=Blocks(b.PlanHistory,l.PlanHistory,c.PlanHistory,origin,"고정 계획",force);d.PlanHistoryIds=Set(b.PlanHistoryIds,l.PlanHistoryIds,c.PlanHistoryIds);foreach(var h in d.PlanHistory)if(!d.PlanHistoryIds.Contains(h.Id))d.PlanHistoryIds.Add(h.Id);d.AnchorReferences=Map(b.AnchorReferences,l.AnchorReferences,c.AnchorReferences,"계획 기준 시각",force);d.AnchorCounts=Map(b.AnchorCounts,l.AnchorCounts,c.AnchorCounts,"계획 기준 길이",force);
   Adherence.Reconcile(d,new[]{l,c});
   merged.CategorySettings=Entities(baseline.CategorySettings,local.CategorySettings,current.CategorySettings,x=>x.name,"카테고리",force);var baseOrder=baseline.CategorySettings.Select(x=>x.name).ToList();var localOrder=local.CategorySettings.Select(x=>x.name).ToList();if(!Same(baseOrder,localOrder)){var positions=localOrder.Select((k,i)=>new{k,i}).ToDictionary(x=>x.k,x=>x.i);merged.CategorySettings=merged.CategorySettings.OrderBy(x=>positions.ContainsKey(x.name)?positions[x.name]:int.MaxValue).ToList();}
   merged.BlankSatisfactionValue=Pick(baseline.BlankSatisfactionValue,local.BlankSatisfactionValue,current.BlankSatisfactionValue,"빈칸 만족도",force);merged.ExcludeBlankSatisfaction=Pick(baseline.ExcludeBlankSatisfaction,local.ExcludeBlankSatisfaction,current.ExcludeBlankSatisfaction,"빈칸 집계",force);merged.Tasks=Tasks(baseline.Tasks,local.Tasks,current.Tasks,force);merged.Template=Pick(baseline.Template,local.Template,current.Template,"일정 기본값",force);merged.DayMinutes=Pick(baseline.DayMinutes,local.DayMinutes,current.DayMinutes,"하루 길이",force);merged.ReminderMinutes=Pick(baseline.ReminderMinutes,local.ReminderMinutes,current.ReminderMinutes,"알림 간격",force);
   merged.Days.Remove(c);merged.Days.Add(d);GridEngine.Build(merged,d);Engine.Validate(merged);return merged;
  }
  public static State Slice(State s,string date){var copy=Store.Clone(s);var d=copy.GetDay(PhoneCodec.Date(date));GridEngine.Build(copy,d);copy.Days=new List<Day>{d};copy.RemoteReceipts=new List<RemoteReceipt>();return copy;}
  public static ReplicaReply Reply(State s,string date){var raw=Encoding.UTF8.GetString(PhoneCodec.Json(Slice(s,date)));return new ReplicaReply{state=raw,revision=PhoneCodec.Hash(Encoding.UTF8.GetBytes(raw)),view=PhoneCodec.Snapshot(s,date)};}
 }
 public partial class MainForm {
  public ReplicaReply ReplicaSnapshot(string date){SaveNote();return ReplicaSync.Reply(Data,date);}
  public ReplicaReply ReplicaApply(ReplicaInput input){SaveNote();PhoneCodec.Date(input.date);if(input.baseState==null||input.localState==null||input.baseState.Length>1500000||input.localState.Length>1500000)throw new InvalidDataException("동기화 데이터 크기를 확인해 주세요.");var current=ReplicaSync.Reply(Data,input.date);if(input.preferLocal&&input.expectedRevision!=current.revision)throw new SyncConflict("선택하는 동안 PC 기록이 다시 바뀌었습니다. 내용을 다시 확인해 주세요.");var baseline=PhoneCodec.Read<State>(Encoding.UTF8.GetBytes(input.baseState));var local=PhoneCodec.Read<State>(Encoding.UTF8.GetBytes(input.localState));if(baseline.Days.Count!=1||local.Days.Count!=1||baseline.Days[0].Date!=input.date||local.Days[0].Date!=input.date)throw new InvalidDataException("하루씩 동기화해 주세요.");var edited=ReplicaSync.Merge(baseline,local,Data,input.date,input.preferLocal);string path=System.IO.Path.Combine(System.IO.Path.GetDirectoryName(Store.PathName),"before-offline-"+DateTime.UtcNow.ToString("yyyyMMddHHmmssfff")+".json");File.WriteAllBytes(path,PhoneCodec.Json(Data));undo=Data;Store.Save(edited);Data=edited;Day=Data.GetDay(PhoneCodec.Date(Day.Date));RefreshAll();Diagnostics.Action("offline-sync",input.date);return ReplicaSync.Reply(Data,input.date);}
 }
}
